-- =========================================================================
-- Rollback for 20260901000031_admin_mfa_everywhere.sql. Restores the 030
-- definitions exactly (generated by scripts/migrations/generate-031.mjs).
-- Afterwards a password-only admin again has editor-level access (030).
-- Run inside a transaction. Not in supabase/migrations/ — never auto-applied.
-- =========================================================================
CREATE OR REPLACE FUNCTION public.commit_asset_import(p_collection asset_collection, p_filename text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role user_role;
  v_row jsonb;
  v_n int;
  v_serial text;
  v_key text;
  v_matches int;
  v_hit serial_keys;
  v_cur record;
  v_history text;
  v_name text;
  v_category text;
  v_location text;
  v_status text;
  v_assignee text;
  v_changes text[];
  v_new_id uuid;
  v_created int := 0;
  v_updated int := 0;
  v_unchanged int := 0;
  v_rejected int := 0;
  v_issues jsonb := '[]'::jsonb;
  v_laptops constant text[] := array['serialized_assets', 'active_laptops_np'];
begin
  select role into v_role from profiles where id = v_actor;
  if v_role is null or v_role not in ('admin', 'editor') then
    raise exception 'Not authorized to import';
  end if;
  -- Assignment changes made below (none should be) are marked as imports
  -- for the register's sync trigger (20260901000026).
  perform set_config('equipment.context', 'import', true);

  for v_row, v_n in select value, ordinality from jsonb_array_elements(p_rows) with ordinality
  loop
    v_serial := btrim(coalesce(v_row ->> 'serial', ''));
    v_key := normalize_serial(v_serial);
    v_name := nullif(btrim(coalesce(v_row ->> 'name', '')), '');
    v_category := nullif(btrim(coalesce(v_row ->> 'category', '')), '');
    v_location := nullif(btrim(coalesce(v_row ->> 'location', '')), '');
    v_status := nullif(lower(btrim(coalesce(v_row ->> 'status', ''))), '');
    v_assignee := nullif(btrim(coalesce(v_row ->> 'assigned_to', '')), '');

    if v_key = '' then
      v_rejected := v_rejected + 1;
      v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'rejected', 'reason', 'Missing serial number');
      continue;
    end if;
    if v_status is not null and not (v_status = any (enum_range(null::asset_status)::text[])) then
      v_rejected := v_rejected + 1;
      v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'rejected', 'reason', format('Invalid status "%s"', v_status));
      continue;
    end if;

    select count(*) into v_matches from serial_keys where serial_key = v_key;
    if v_matches > 1 then
      v_rejected := v_rejected + 1;
      v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'rejected',
        'reason', 'More than one device already has this serial — resolve the duplicate first');
      continue;
    end if;
    select * into v_hit from serial_keys where serial_key = v_key;

    if v_hit.asset_id is not null then
      -- ------------------------------------------------ existing device
      if v_hit.collection::text <> p_collection::text
         and not (v_hit.collection::text = any (v_laptops) and p_collection::text = any (v_laptops)) then
        v_rejected := v_rejected + 1;
        v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'rejected',
          'collection', v_hit.collection, 'asset_id', v_hit.asset_id,
          'reason', format('This serial already belongs to a device in %s', replace(v_hit.collection::text, '_', ' ')));
        continue;
      end if;

      execute format('select name, category, location, status::text as status, assigned_to from %I where id = $1', v_hit.collection)
        into v_cur using v_hit.asset_id;

      -- Ownership and lifecycle are never changed by an import: report.
      if v_status is not null and v_status <> v_cur.status then
        v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'not_applied',
          'collection', v_hit.collection, 'asset_id', v_hit.asset_id, 'field', 'status',
          'current', v_cur.status, 'requested', v_status,
          'reason', 'Status changes need a lifecycle action on the device — not applied');
      end if;
      if v_assignee is not null and normalize_person_name(v_assignee) is distinct from normalize_person_name(v_cur.assigned_to) then
        v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'not_applied',
          'collection', v_hit.collection, 'asset_id', v_hit.asset_id, 'field', 'assigned_to',
          'current', v_cur.assigned_to, 'requested', v_assignee,
          'reason', 'Assignment changes need Provide / Transfer / Collect on the device — not applied');
      end if;

      -- Metadata: only non-empty, different values.
      v_changes := array[]::text[];
      if v_name is not null and v_name is distinct from v_cur.name then
        v_changes := v_changes || format('name "%s" → "%s"', v_cur.name, v_name);
      else
        v_name := v_cur.name;
      end if;
      if v_category is not null and v_category is distinct from v_cur.category then
        v_changes := v_changes || format('category "%s" → "%s"', v_cur.category, v_category);
      else
        v_category := v_cur.category;
      end if;
      if v_location is not null and v_location is distinct from v_cur.location then
        v_changes := v_changes || format('location "%s" → "%s"', coalesce(v_cur.location, ''), v_location);
      else
        v_location := v_cur.location;
      end if;

      if cardinality(v_changes) = 0 then
        v_unchanged := v_unchanged + 1;
        continue;
      end if;
      execute format('update %I set name = $1, category = $2, location = $3 where id = $4', v_hit.collection)
        using v_name, v_category, v_location, v_hit.asset_id;
      v_history := case v_hit.collection::text when 'serialized_assets' then 'serialized_asset_history' else v_hit.collection::text || '_history' end;
      execute format('insert into %I (asset_id, action, detail, actor_user_id) values ($1, $2, $3, $4)', v_history)
        using v_hit.asset_id, 'imported', format('Updated via import from %s: %s', p_filename, array_to_string(v_changes, '; ')), v_actor;
      v_updated := v_updated + 1;
    else
      -- ------------------------------------------------------ new device
      if v_name is null or v_category is null then
        v_rejected := v_rejected + 1;
        v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'rejected', 'reason', 'Name and category are required for a new device');
        continue;
      end if;
      if v_assignee is not null or v_status in ('provided', 'retained', 'lost') then
        v_rejected := v_rejected + 1;
        v_issues := v_issues || jsonb_build_object('row', v_n, 'serial', v_serial, 'kind', 'rejected',
          'reason', 'A new device can''t be imported as assigned, Provided, Retained or Lost — import it without Status/Assigned to, then use Provide on the device');
        continue;
      end if;
      execute format('insert into %I (name, category, serial, status, location) values ($1, $2, $3, $4, $5) returning id', p_collection)
        into v_new_id using v_name, v_category, v_serial, coalesce(v_status, 'available')::asset_status, v_location;
      v_history := case p_collection::text when 'serialized_assets' then 'serialized_asset_history' else p_collection::text || '_history' end;
      execute format('insert into %I (asset_id, action, detail, actor_user_id) values ($1, $2, $3, $4)', v_history)
        using v_new_id, 'created', 'Imported from ' || p_filename, v_actor;
      v_created := v_created + 1;
    end if;
  end loop;

  insert into import_events
    (imported_by, target_collection, filename, rows_created, rows_updated, rows_errored, summary)
  values
    (v_actor, p_collection::text, p_filename, v_created, v_updated, v_rejected,
     jsonb_build_object('total', jsonb_array_length(p_rows), 'unchanged', v_unchanged, 'issues', v_issues));

  perform set_config('equipment.context', '', true);
  return jsonb_build_object('created', v_created, 'updated', v_updated, 'unchanged', v_unchanged,
                            'rejected', v_rejected, 'issues', v_issues);
end;
$function$;

CREATE OR REPLACE FUNCTION public.commit_bulk_import(p_filename text, p_rows jsonb, p_confirm_repeat boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role user_role;
  v_row record;
  v_id uuid;
  v_hash text;
  v_dupe text;
  v_prev bulk_import_receipts;
  v_event uuid;
  v_created int := 0;
  v_updated int := 0;
  v_unchanged int := 0;
begin
  select role into v_role from profiles where id = v_actor;
  if v_role is null or v_role not in ('admin', 'editor') then
    raise exception 'Not authorized to import';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'Nothing to import';
  end if;

  drop table if exists pg_temp.bulk_import_rows;
  create temporary table bulk_import_rows on commit drop as
  select e.ord, btrim(coalesce(e.r ->> 'name', '')) as name, btrim(coalesce(e.r ->> 'category', '')) as category,
         nullif(btrim(coalesce(e.r ->> 'location', '')), '') as location,
         nullif(btrim(coalesce(e.r ->> 'quantity', '')), '') as qty_text
  from jsonb_array_elements(p_rows) with ordinality as e(r, ord);

  if exists (select 1 from bulk_import_rows where name = '' or category = '') then
    raise exception 'Every row needs a name and a category';
  end if;
  if exists (select 1 from bulk_import_rows where qty_text is not null and qty_text !~ '^[0-9]+$') then
    raise exception 'Quantities must be whole numbers of 0 or more';
  end if;
  select string_agg(format('"%s" (%s)', n, c), ', ') into v_dupe
  from (select min(name) as n, min(category) as c from bulk_import_rows
        group by bulk_item_key(name), bulk_item_key(category) having count(*) > 1) d;
  if v_dupe is not null then
    raise exception 'The file lists the same item more than once: % — combine those rows into one', v_dupe;
  end if;

  -- What this delivery contains, independent of file name, row order,
  -- capitalisation and spacing.
  select md5(string_agg(bulk_item_key(name) || '|' || bulk_item_key(category) || '|' || coalesce(qty_text::int, 0)::text, E'\n'
                        order by bulk_item_key(name), bulk_item_key(category)))
    into v_hash from bulk_import_rows;
  -- Imports of the same content run one after the other, never together.
  perform pg_advisory_xact_lock(hashtext('commit_bulk_import'), hashtext(v_hash));
  select * into v_prev from bulk_import_receipts where content_hash = v_hash order by imported_at desc limit 1;
  if v_prev.id is not null and not p_confirm_repeat then
    return jsonb_build_object('created', 0, 'updated', 0, 'unchanged', 0,
      'duplicate_of', jsonb_build_object('filename', v_prev.filename, 'imported_at', v_prev.imported_at,
        'imported_by', (select email from profiles where id = v_prev.imported_by)));
  end if;

  for v_row in select * from bulk_import_rows order by ord loop
    select id into v_id from bulk_items
     where bulk_item_key(name) = bulk_item_key(v_row.name) and bulk_item_key(category) = bulk_item_key(v_row.category);
    if v_id is null then
      insert into bulk_items (name, category, location, available)
      values (v_row.name, v_row.category, v_row.location, coalesce(v_row.qty_text::int, 0))
      returning id into v_id;
      insert into bulk_item_history (item_id, action, detail, quantity, actor_user_id)
      values (v_id, 'created', 'Imported from ' || p_filename, coalesce(v_row.qty_text::int, 0), v_actor);
      v_created := v_created + 1;
    elsif coalesce(v_row.qty_text::int, 0) > 0 then
      update bulk_items set available = available + v_row.qty_text::int where id = v_id;
      insert into bulk_item_history (item_id, action, detail, quantity, actor_user_id)
      values (v_id, 'receive_stock', 'Received via import from ' || p_filename
                || case when v_prev.id is not null then ' (confirmed as a new delivery of an earlier file)' else '' end,
              v_row.qty_text::int, v_actor);
      v_updated := v_updated + 1;
    else
      v_unchanged := v_unchanged + 1;
    end if;
  end loop;

  insert into import_events (imported_by, target_collection, filename, rows_created, rows_updated, rows_errored, summary)
  values (v_actor, 'bulk_items', p_filename, v_created, v_updated, 0,
          jsonb_build_object('total', v_created + v_updated + v_unchanged, 'unchanged', v_unchanged,
                             'content_hash', v_hash, 'repeat_of', v_prev.id))
  returning id into v_event;
  insert into bulk_import_receipts (content_hash, filename, import_event_id, repeat_of, imported_by)
  values (v_hash, p_filename, v_event, v_prev.id, v_actor);

  return jsonb_build_object('created', v_created, 'updated', v_updated, 'unchanged', v_unchanged, 'repeat_of', v_prev.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_asset(p_collection asset_collection, p_name text, p_category text, p_serial text, p_status asset_status DEFAULT 'available'::asset_status, p_assigned_to text DEFAULT NULL::text, p_location text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_table text := p_collection::text;
  v_history_table text := case p_collection
    when 'serialized_assets' then 'serialized_asset_history'
    when 'active_laptops_np' then 'active_laptops_np_history'
    when 'monitors' then 'monitors_history'
    when 'other_equipment' then 'other_equipment_history'
  end;
  v_actor uuid := auth.uid();
  v_role user_role;
  v_id uuid;
begin
  select role into v_role from profiles where id = v_actor;

  if v_role is null or v_role = 'viewer' then
    raise exception 'Not authorized to add assets';
  end if;

  execute format(
    'insert into %I (name, category, serial, status, assigned_to, location) values ($1,$2,$3,$4,$5,$6) returning id',
    v_table
  )
  into v_id
  using p_name, p_category, p_serial, p_status, p_assigned_to, p_location;

  execute format(
    'insert into %I (asset_id, action, detail, actor_user_id) values ($1, $2, $3, $4)',
    v_history_table
  ) using v_id, 'created', 'Added to ' || v_table, v_actor;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_bulk_item(p_name text, p_category text, p_location text DEFAULT NULL::text, p_initial_quantity integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role user_role;
  v_id uuid;
  v_qty integer := coalesce(p_initial_quantity, 0);
begin
  select role into v_role from profiles where id = v_actor;
  if v_role is null or v_role not in ('admin', 'editor') then
    raise exception 'Not authorized to add bulk stock items';
  end if;
  if v_qty < 0 then
    raise exception 'Initial quantity cannot be negative';
  end if;

  begin
    insert into bulk_items (name, category, location, available)
    values (p_name, p_category, p_location, v_qty)
    returning id into v_id;
  exception when unique_violation then
    raise exception 'A Bulk Stock item "%" in category "%" already exists — use Receive stock on it instead', btrim(p_name), btrim(p_category)
      using errcode = 'unique_violation';
  end;

  insert into bulk_item_history (item_id, action, detail, quantity, actor_user_id)
  values (v_id, 'created', 'Added to bulk stock', v_qty, v_actor);

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.onboarding_assign_device(p_onboarding_id uuid, p_serial text, p_name text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_location text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role user_role;
  v_employee text;
  v_asset_id uuid;
  v_status asset_status;
  v_row record;
begin
  select role into v_role from profiles where id = v_actor;
  if v_role is null or v_role not in ('admin', 'editor') then
    raise exception 'Not authorized';
  end if;

  select employee_name into v_employee from onboarding_checklists where id = p_onboarding_id;
  if v_employee is null then
    raise exception 'Onboarding record not found';
  end if;

  select id, status into v_asset_id, v_status
    from active_laptops_np where serial = p_serial for update;

  if v_asset_id is null then
    -- Not a Next Perimeter laptop already — it may instead be sitting
    -- unprovided in Laptop Inventory, which is the primary pool laptops
    -- are provided from since this migration.
    select * into v_row from serialized_assets where serial = p_serial for update;
    if v_row.id is not null then
      insert into active_laptops_np
        (id, name, category, serial, status, assigned_to, location, created_at, updated_at, moved_from_inventory)
      values
        (v_row.id, v_row.name, v_row.category, v_row.serial, v_row.status, v_row.assigned_to, v_row.location, v_row.created_at, now(), true);

      insert into active_laptops_np_history (asset_id, date, action, detail, actor_user_id)
      select asset_id, date, action, detail, actor_user_id from serialized_asset_history where asset_id = v_row.id;

      delete from serialized_assets where id = v_row.id;

      v_asset_id := v_row.id;
      v_status := v_row.status;
    end if;
  end if;

  if v_asset_id is null then
    if p_name is null or p_category is null then
      raise exception 'name and category are required to add a new device for serial %', p_serial;
    end if;

    insert into active_laptops_np (name, category, serial, status, location)
    values (p_name, p_category, p_serial, 'available', p_location)
    returning id into v_asset_id;

    insert into active_laptops_np_history (asset_id, action, detail, actor_user_id)
    values (v_asset_id, 'created', 'Added during onboarding for ' || v_employee, v_actor);

    v_status := 'available';
  end if;

  if v_status not in ('available', 'retained', 'decommissioned') then
    raise exception 'Device % is not available to assign (currently %)', p_serial, v_status;
  end if;

  update active_laptops_np set status = 'provided', assigned_to = v_employee where id = v_asset_id;

  insert into active_laptops_np_history (asset_id, action, detail, actor_user_id)
  values (v_asset_id, 'provide', 'Assigned during onboarding for ' || v_employee, v_actor);

  update onboarding_checklists
    set equipment_assigned = true, assigned_asset_id = v_asset_id
    where id = p_onboarding_id;

  return v_asset_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.perform_bulk_action(p_item_id uuid, p_action bulk_action, p_quantity integer, p_from_bucket bulk_bucket DEFAULT NULL::bulk_bucket, p_detail text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_role user_role;
  v_from bulk_bucket;
  v_to bulk_bucket;
  v_current integer;
  v_found boolean;
begin
  select role into v_role from profiles where id = v_actor;
  if v_role is null or v_role not in ('admin', 'editor') then
    raise exception 'Not authorized to modify bulk stock';
  end if;

  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Quantity must be a positive number';
  end if;

  v_from := case p_action
    when 'receive_stock' then null
    when 'issue' then 'available'::bulk_bucket
    when 'return' then 'provided'::bulk_bucket
    when 'retain' then 'available'::bulk_bucket
    when 'repair' then 'damaged'::bulk_bucket
    when 'mark_damaged' then p_from_bucket
    when 'decommission' then p_from_bucket
  end;

  v_to := case p_action
    when 'receive_stock' then 'available'::bulk_bucket
    when 'issue' then 'provided'::bulk_bucket
    when 'return' then 'available'::bulk_bucket
    when 'retain' then 'retained'::bulk_bucket
    when 'repair' then 'available'::bulk_bucket
    when 'mark_damaged' then 'damaged'::bulk_bucket
    when 'decommission' then 'decommissioned'::bulk_bucket
  end;

  if p_action in ('mark_damaged', 'decommission') and v_from is null then
    raise exception 'from_bucket is required for %', p_action;
  end if;

  if v_from is not null then
    execute format('select %I from bulk_items where id = $1 for update', v_from::text)
      into v_current
      using p_item_id;

    if not found then
      raise exception 'Bulk item not found';
    end if;
    if v_current < p_quantity then
      raise exception 'Insufficient quantity in % (have %, need %)', v_from, v_current, p_quantity;
    end if;

    execute format('update bulk_items set %I = %I - $1 where id = $2', v_from::text, v_from::text)
      using p_quantity, p_item_id;
  else
    perform 1 from bulk_items where id = p_item_id for update;
    if not found then
      raise exception 'Bulk item not found';
    end if;
  end if;

  execute format('update bulk_items set %I = %I + $1 where id = $2', v_to::text, v_to::text)
    using p_quantity, p_item_id;

  insert into bulk_item_history (item_id, action, detail, quantity, actor_user_id)
  values (p_item_id, p_action::text, nullif(p_detail, ''), p_quantity, v_actor);
end;
$function$;

CREATE OR REPLACE FUNCTION public.perform_lifecycle_action(p_collection asset_collection, p_asset_id uuid, p_action asset_action, p_assigned_to text DEFAULT NULL::text, p_detail text DEFAULT NULL::text)
 RETURNS asset_collection
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_table text := p_collection::text;
  v_history_table text := case p_collection
    when 'serialized_assets' then 'serialized_asset_history'
    when 'active_laptops_np' then 'active_laptops_np_history'
    when 'monitors' then 'monitors_history'
    when 'other_equipment' then 'other_equipment_history'
  end;
  v_actor uuid := auth.uid();
  v_role user_role;
  v_current_status asset_status;
  v_new_status asset_status;
  v_moved_from_inventory boolean;
  v_row record;
begin
  select role into v_role from profiles where id = v_actor;

  if v_role is null then
    raise exception 'Not authorized';
  end if;
  if v_role = 'viewer' then
    raise exception 'Viewers cannot perform lifecycle actions';
  end if;
  if v_role = 'scanner' and p_action not in ('provide', 'collect') then
    raise exception 'Scanners can only Provide or Collect';
  end if;

  execute format('select status from %I where id = $1 for update', v_table)
    into v_current_status
    using p_asset_id;

  if v_current_status is null then
    raise exception 'Asset not found in %', v_table;
  end if;

  v_new_status := case
    when p_action = 'provide' and v_current_status in ('available', 'retained', 'decommissioned')
      then 'provided'::asset_status
    when p_action = 'retain' and v_current_status in ('available', 'decommissioned')
      then 'retained'::asset_status
    when p_action = 'mark_damaged' and v_current_status in ('available', 'provided', 'retained', 'decommissioned')
      then 'damaged'::asset_status
    when p_action = 'collect' and v_current_status = 'provided'
      then 'available'::asset_status
    when p_action = 'transfer' and v_current_status = 'provided'
      then 'provided'::asset_status
    when p_action = 'decommission' and v_current_status = 'provided'
      then 'decommissioned'::asset_status
    when p_action = 'mark_repaired' and v_current_status = 'damaged'
      then 'available'::asset_status
    when p_action = 'mark_nonfunctional' and v_current_status = 'damaged'
      then 'nonfunctional'::asset_status
    else null
  end;

  if v_new_status is null then
    raise exception 'Action % is not allowed from status %', p_action, v_current_status;
  end if;

  if p_action in ('provide', 'transfer') and coalesce(btrim(p_assigned_to), '') = '' then
    raise exception 'assigned_to is required for %', p_action;
  end if;

  -- Laptop Inventory -> Active Laptops (NP): Provide moves the row instead
  -- of updating it in place.
  if p_collection = 'serialized_assets' and p_action = 'provide' then
    select * into v_row from serialized_assets where id = p_asset_id;

    insert into active_laptops_np
      (id, name, category, serial, status, assigned_to, location, created_at, updated_at, moved_from_inventory)
    values
      (v_row.id, v_row.name, v_row.category, v_row.serial, 'provided', p_assigned_to, v_row.location, v_row.created_at, now(), true);

    insert into active_laptops_np_history (asset_id, date, action, detail, actor_user_id)
    select asset_id, date, action, detail, actor_user_id from serialized_asset_history where asset_id = p_asset_id;

    insert into active_laptops_np_history (asset_id, action, detail, actor_user_id)
    values (p_asset_id, 'provide', nullif(p_detail, ''), v_actor);

    delete from serialized_assets where id = p_asset_id; -- cascades serialized_asset_history

    return 'active_laptops_np'::asset_collection;
  end if;

  -- Active Laptops (NP) -> Laptop Inventory: Collect/Decommission on a
  -- laptop that arrived here via the move above returns it to Inventory. A
  -- genuine Next Perimeter laptop (moved_from_inventory = false) never
  -- moves — it stays here regardless of status, same as before this change.
  if p_collection = 'active_laptops_np' and p_action in ('collect', 'decommission') then
    select moved_from_inventory into v_moved_from_inventory
      from active_laptops_np where id = p_asset_id;

    if v_moved_from_inventory then
      select * into v_row from active_laptops_np where id = p_asset_id;

      insert into serialized_assets
        (id, name, category, serial, status, assigned_to, location, created_at, updated_at)
      values
        (v_row.id, v_row.name, v_row.category, v_row.serial, v_new_status, null, v_row.location, v_row.created_at, now());

      insert into serialized_asset_history (asset_id, date, action, detail, actor_user_id)
      select asset_id, date, action, detail, actor_user_id from active_laptops_np_history where asset_id = p_asset_id;

      insert into serialized_asset_history (asset_id, action, detail, actor_user_id)
      values (p_asset_id, p_action::text, nullif(p_detail, ''), v_actor);

      delete from active_laptops_np where id = p_asset_id; -- cascades active_laptops_np_history

      return 'serialized_assets'::asset_collection;
    end if;
  end if;

  if p_action in ('provide', 'transfer') then
    execute format('update %I set status = $1, assigned_to = $2 where id = $3', v_table)
      using v_new_status, p_assigned_to, p_asset_id;
  elsif p_action in ('collect', 'decommission') then
    execute format('update %I set status = $1, assigned_to = null where id = $2', v_table)
      using v_new_status, p_asset_id;
  else
    execute format('update %I set status = $1 where id = $2', v_table)
      using v_new_status, p_asset_id;
  end if;

  execute format(
    'insert into %I (asset_id, action, detail, actor_user_id) values ($1, $2, $3, $4)',
    v_history_table
  ) using p_asset_id, p_action::text, nullif(p_detail, ''), v_actor;

  return p_collection;
end;
$function$;

CREATE OR REPLACE FUNCTION public.perform_swap(p_collection asset_collection, p_old_asset_id uuid, p_new_asset_id uuid, p_reason text)
 RETURNS asset_collection
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_table text := p_collection::text;
  v_history_table text := case p_collection
    when 'serialized_assets' then 'serialized_asset_history'
    when 'active_laptops_np' then 'active_laptops_np_history'
    when 'monitors' then 'monitors_history'
    when 'other_equipment' then 'other_equipment_history'
  end;
  v_actor uuid := auth.uid();
  v_role user_role;
  v_old_status asset_status;
  v_old_serial text;
  v_assignee text;
  v_old_moved_from_inventory boolean := false;
  v_new_status asset_status;
  v_new_serial text;
  v_new_in_inventory boolean := false;
  v_row record;
begin
  select role into v_role from profiles where id = v_actor;
  if v_role is null or v_role not in ('admin', 'editor') then
    raise exception 'Not authorized to perform a swap';
  end if;

  if p_old_asset_id = p_new_asset_id then
    raise exception 'Cannot swap an asset with itself';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'A reason is required for a swap';
  end if;

  execute format('select status, serial, assigned_to from %I where id = $1 for update', v_table)
    into v_old_status, v_old_serial, v_assignee
    using p_old_asset_id;
  if v_old_status is null then
    raise exception 'Asset not found';
  end if;
  if v_old_status <> 'provided' then
    raise exception 'Swap is only allowed while the asset is provided (currently %)', v_old_status;
  end if;

  if p_collection = 'active_laptops_np' then
    select moved_from_inventory into v_old_moved_from_inventory
      from active_laptops_np where id = p_old_asset_id;
  end if;

  execute format('select status, serial from %I where id = $1 for update', v_table)
    into v_new_status, v_new_serial
    using p_new_asset_id;

  if v_new_status is null and p_collection = 'active_laptops_np' then
    select status, serial into v_new_status, v_new_serial
      from serialized_assets where id = p_new_asset_id for update;
    if v_new_status is not null then
      v_new_in_inventory := true;
    end if;
  end if;

  if v_new_status is null then
    raise exception 'Replacement asset not found';
  end if;
  if v_new_status not in ('available', 'decommissioned') then
    raise exception 'Replacement asset must be available or decommissioned (currently %)', v_new_status;
  end if;

  -- ---------------------------------------------------------- old asset
  execute format('update %I set status = $1, assigned_to = null where id = $2', v_table)
    using 'damaged'::asset_status, p_old_asset_id;
  execute format(
    'insert into %I (asset_id, action, detail, actor_user_id) values ($1, $2, $3, $4)',
    v_history_table
  ) using p_old_asset_id, 'swap',
    format('Swapped out (reason: %s). Replaced by serial %s.', p_reason, v_new_serial), v_actor;

  if v_old_moved_from_inventory then
    select * into v_row from active_laptops_np where id = p_old_asset_id;

    insert into serialized_assets
      (id, name, category, serial, status, assigned_to, location, created_at, updated_at)
    values
      (v_row.id, v_row.name, v_row.category, v_row.serial, 'damaged', null, v_row.location, v_row.created_at, now());

    insert into serialized_asset_history (asset_id, date, action, detail, actor_user_id)
    select asset_id, date, action, detail, actor_user_id from active_laptops_np_history where asset_id = p_old_asset_id;

    delete from active_laptops_np where id = p_old_asset_id;
  end if;

  -- ---------------------------------------------------------- new asset
  if v_new_in_inventory then
    select * into v_row from serialized_assets where id = p_new_asset_id;

    insert into active_laptops_np
      (id, name, category, serial, status, assigned_to, location, created_at, updated_at, moved_from_inventory)
    values
      (v_row.id, v_row.name, v_row.category, v_row.serial, 'provided', v_assignee, v_row.location, v_row.created_at, now(), true);

    insert into active_laptops_np_history (asset_id, date, action, detail, actor_user_id)
    select asset_id, date, action, detail, actor_user_id from serialized_asset_history where asset_id = p_new_asset_id;

    insert into active_laptops_np_history (asset_id, action, detail, actor_user_id)
    values (p_new_asset_id, 'swap',
      format('Swapped in (reason: %s). Replaces serial %s.', p_reason, v_old_serial), v_actor);

    delete from serialized_assets where id = p_new_asset_id;
  else
    execute format('update %I set status = $1, assigned_to = $2 where id = $3', v_table)
      using 'provided'::asset_status, v_assignee, p_new_asset_id;
    execute format(
      'insert into %I (asset_id, action, detail, actor_user_id) values ($1, $2, $3, $4)',
      v_history_table
    ) using p_new_asset_id, 'swap',
      format('Swapped in (reason: %s). Replaces serial %s.', p_reason, v_old_serial), v_actor;
  end if;

  if v_old_moved_from_inventory then
    return 'serialized_assets'::asset_collection;
  end if;
  return p_collection;
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_known_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select not is_anonymous_session()
     and exists (select 1 from profiles where id = auth.uid() and access_revoked_at is null);
$function$;

CREATE OR REPLACE FUNCTION public.is_editor_or_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select not is_anonymous_session()
     and coalesce(
       (select role from profiles where id = auth.uid() and access_revoked_at is null) in ('admin', 'editor'),
       false
     );
$function$;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select not is_anonymous_session()
     and current_aal() = 'aal2'
     and coalesce((select role from profiles where id = auth.uid() and access_revoked_at is null) = 'admin', false);
$function$;

drop trigger profiles_require_mfa_for_new_admin on profiles;
drop function require_mfa_for_new_admin();
drop policy profiles_select_self on profiles;
drop function session_role();
